53	+import { copyFile, mkdir, mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
54	+import { tmpdir } from 'node:os';
55	+import { basename, dirname, join } from 'node:path';
56	+import { pathToFileURL } from 'node:url';
57	+import type { HarnessDefaults, ModelCatalogEntry } from '@graphgoblin/contracts';
58	+import { FakeHarness } from '@graphgoblin/engine/testing';
59	+import {
60	+  DEFAULT_MODEL_CATALOG,
61	+  SqliteModelCatalog,
62	+  databaseView,
63	+  openDatabase,
64	+  openReadOnlyDatabaseClient,
65	+} from '@graphgoblin/infrastructure/sqlite';
66	+import { afterEach, beforeEach, describe, expect, it } from 'vitest';
67	+import { loadConfig } from './config.js';
68	+import { createContainer } from './container.js';
69	+import { runPreflightCli } from './preflight.js';
70	+
71	+const KEY = Buffer.alloc(32, 8).toString('base64');
72	+let dir: string;
73	+
74	+beforeEach(async () => {
75	+  dir = await mkdtemp(join(tmpdir(), 'gg-preflight-catalog-'));
76	+});
77	+
78	+afterEach(async () => {
79	+  globalThis.gc?.();
80	+  await rm(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 });
81	+});
82	+
83	+function adapters() {
84	+  return {
85	+    harnesses: { codex: new FakeHarness(), claude: new FakeHarness([], 'claude') },
86	+    deciders: [],
87	+    startTimers: false,
88	+  };
89	+}
90	+
91	+function env(dbFile: string, defaults: HarnessDefaults): Record<string, string> {
92	+  return {
93	+    GG_DATA_DIR: join(dir, 'data'),
94	+    GG_DB_URL: pathToFileURL(dbFile).href,
95	+    GG_MASTER_KEY: KEY,
96	+    GG_DEFAULTS: JSON.stringify(defaults),
97	+  };
98	+}
99	+
100	+async function cli(environment: Record<string, string>) {
101	+  let out = '';
102	+  const code = await runPreflightCli({
103	+    env: environment,
104	+    ...adapters(),
105	+    write: (text) => {
106	+      out += text;
107	+    },
108	+  });
109	+  return { code, out };
110	+}
111	+
112	+async function fixture(dbFile: string, rows = DEFAULT_MODEL_CATALOG) {
113	+  await mkdir(dirname(dbFile), { recursive: true });
114	+  const handle = openDatabase({ url: pathToFileURL(dbFile).href });
115	+  try {
116	+    await handle.migrate();
117	+    await new SqliteModelCatalog(handle.db).seed(rows);
118	+    await handle.client.execute('PRAGMA wal_checkpoint(TRUNCATE)');
119	+  } finally {
120	+    handle.close();
121	+  }
122	+}
123	+
124	+/** SQLite readers update -shm read marks; only DB/WAL contain the stored data. */
125	+async function storeBytes(dbFile: string) {
126	+  const names = (await readdir(dirname(dbFile))).filter(
127	+    (name) => name === basename(dbFile) || name === `${basename(dbFile)}-wal`,
128	+  );
129	+  return Object.fromEntries(
130	+    await Promise.all(
131	+      names.map(async (name): Promise<[string, Buffer]> => [
132	+        name,
133	+        await readFile(join(dirname(dbFile), name)),
134	+      ]),
135	+    ),
136	+  );
137	+}
138	+
139	+async function storedCatalog(dbFile: string) {
140	+  const client = openReadOnlyDatabaseClient(dbFile);
141	+  try {
142	+    return await new SqliteModelCatalog(databaseView(client)).list();
143	+  } finally {
144	+    client.close();
145	+  }
146	+}
147	+
148	+describe('offline startup catalog admission', () => {
149	+  it.each([
150	+    ['codex', 'gpt-6.1-terra', 'medium'],
151	+    ['claude', 'claude-opus-5-5', 'high'],
152	+  ] as const)(
153	+    'accepts a missing shipped %s seed without storing it',
154	+    async (harness, model, effort) => {
155	+      // The DB is outside GG_DATA_DIR and its URL is percent-encoded: both paths use startup's
156	+      // projected catalog. This simulates a current-format store before its first upgrade start.
157	+      const dbFile = join(dir, 'external store', 'gateway.db');
158	+      await fixture(
159	+        dbFile,
160	+        DEFAULT_MODEL_CATALOG.filter(
161	+          (entry) => !(entry.harness === harness && entry.model === model),
162	+        ),
163	+      );
164	+      const defaults: HarnessDefaults = {
165	+        byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' }, [harness]: { model, effort } },
166	+      };
167	+      const environment = env(dbFile, defaults);
168	+      const before = await storeBytes(dbFile);
169	+      const report = await cli(environment);
170	+      expect(report.code, report.out).toBe(0);
171	+      expect(report.out).toMatch(/ok\s+Database\s+reachable and migrated/);
172	+      expect(report.out).toMatch(
173	+        harness === 'codex'
174	+          ? /ok\s+Default model\s+gpt-6.1-terra \(codex\) is in the model catalog/
175	+          : /ok\s+Claude default model\s+Exact Claude model and effort are configured/,
176	+      );
177	+      expect(await storeBytes(dbFile)).toEqual(before);
178	+      expect(
179	+        (await storedCatalog(dbFile)).some((row) => row.harness === harness && row.model === model),
180	+      ).toBe(false);
181	+      await expect(readdir(environment['GG_DATA_DIR']!)).rejects.toMatchObject({ code: 'ENOENT' });
182	+
183	+      const container = await createContainer(loadConfig(environment), adapters());
184	+      try {
185	+        await container.start();
186	+        expect(await container.repos.catalog.findOne(harness, model)).toMatchObject({
187	+          enabled: true,
188	+        });
189	+      } finally {
190	+        await container.stop();
191	+      }
192	+    },
193	+  );
194	+
195	+  it.each([
196	+    {
197	+      harness: 'codex',
198	+      model: 'gpt-6.1-terra',
199	+      effort: 'medium',
200	+      enabled: false,
201	+      status: 'WARN',
202	+      code: 0,
203	+      refusal: undefined,
204	+    },
205	+    {
206	+      harness: 'claude',
207	+      model: 'claude-opus-5-5',
208	+      effort: 'high',
209	+      enabled: false,
210	+      status: 'FAIL',
211	+      code: 1,
212	+      refusal: undefined,
213	+    },
214	+    {
215	+      harness: 'codex',
216	+      model: 'unknown-model',
217	+      effort: 'low',
218	+      status: 'FAIL',
219	+      code: 1,
220	+      refusal: 'MODEL_NOT_IN_CATALOG',
221	+    },
222	+    {
223	+      harness: 'codex',
224	+      model: 'claude-opus-5-5',
225	+      effort: 'high',
226	+      status: 'FAIL',
227	+      code: 1,
228	+      refusal: 'MODEL_HARNESS_MISMATCH',
229	+    },
230	+    {
231	+      harness: 'claude',
232	+      model: 'gpt-6-luna',
233	+      effort: 'low',
234	+      status: 'FAIL',
235	+      code: 1,
236	+      refusal: 'MODEL_HARNESS_MISMATCH',
237	+    },
238	+    {
239	+      harness: 'claude',
240	+      model: 'claude-opus-5-5',
241	+      effort: 'none',
242	+      status: 'FAIL',
243	+      code: 1,
244	+      refusal: 'EFFORT_UNSUPPORTED',
245	+    },
246	+    {
247	+      harness: 'claude',
248	+      model: 'claude-opus-5-5',
249	+      effort: 'low',
250	+      efforts: ['high'],
251	+      status: 'FAIL',
252	+      code: 1,
253	+      refusal: 'EFFORT_UNSUPPORTED',
254	+    },
255	+    // Codex preflight currently checks membership/enabled, while startup also checks effort.
256	+    {
257	+      harness: 'codex',
258	+      model: 'gpt-5.5',
259	+      effort: 'none',
260	+      status: 'ok',
261	+      code: 0,
262	+      refusal: 'EFFORT_UNSUPPORTED',
263	+    },
264	+  ] as const)(
265	+    'preserves $harness $model defaults (effort=$effort, status=$status)',
266	+    async (test) => {
267	+      const dbFile = join(dir, 'gateway.db');
268	+      const rows: ModelCatalogEntry[] = DEFAULT_MODEL_CATALOG.map((entry) =>
269	+        entry.harness === test.harness && entry.model === test.model
270	+          ? {
271	+              ...entry,
272	+              ...('enabled' in test ? { enabled: test.enabled } : {}),
273	+              ...('efforts' in test ? { efforts: [...test.efforts] } : {}),
274	+            }
275	+          : entry,
276	+      );
277	+      await fixture(dbFile, rows);
278	+      const defaults: HarnessDefaults = {
279	+        byHarness: {
280	+          codex: { model: 'gpt-6-luna', effort: 'low' },
281	+          [test.harness]: { model: test.model, effort: test.effort },
282	+        },
283	+      };
284	+      const environment = env(dbFile, defaults);
285	+      const before = await storeBytes(dbFile);
286	+      const report = await cli(environment);
287	+      expect(report.code, report.out).toBe(test.code);
288	+      expect(report.out).toMatch(
289	+        new RegExp(
290	+          `${test.status}\\s+${test.harness === 'codex' ? 'Default model' : 'Claude default model'}\\s+`,
291	+        ),
292	+      );
293	+      expect(await storedCatalog(dbFile)).toEqual(
294	+        [...rows].sort(
295	+          (a, b) => a.harness.localeCompare(b.harness) || a.model.localeCompare(b.model),
296	+        ),
297	+      );
298	+      expect(await storeBytes(dbFile)).toEqual(before);
299	+      if (test.refusal) {
300	+        const outcome: unknown = await createContainer(loadConfig(environment), adapters()).then(
301	+          async (unexpected) => {
302	+            await unexpected.stop();
303	+            return undefined;
304	+          },
305	+          (error: unknown) => error,
306	+        );
307	+        expect(outcome).toMatchObject({
308	+          code: 'EVALUATION_INVALID_CONFIGURATION',
309	+          details: { code: test.refusal, harness: test.harness },
310	+        });
311	+        expect(await storeBytes(dbFile)).toEqual(before);
312	+      } else {
313	+        // A disabled model is unavailable to execution, but is not malformed configuration:
314	+        // ordinary boot must leave Settings available for correcting the selection.
315	+        const container = await createContainer(loadConfig(environment), adapters());
316	+        try {
317	+          await container.start();
318	+          expect(await container.repos.catalog.findOne(test.harness, test.model)).toMatchObject({
319	+            enabled: false,
320	+          });
321	+          expect(
322	+            await container.repos.catalog.isAllowed(test.harness, test.model, test.effort),
323	+          ).toBe(false);
324	+        } finally {
325	+          await container.stop();
326	+        }
327	+      }
328	+    },
329	+  );
330	+
331	+  it('projects a missing seed from a WAL-backed store without checkpointing or writing it', async () => {
332	+    const original = join(dir, 'gateway.db');
333	+    await fixture(original);
334	+    const copy = join(dir, 'copy');
335	+    await mkdir(copy);
336	+    const holder = openDatabase({ url: pathToFileURL(original).href });
337	+    try {
338	+      await holder.client.execute('PRAGMA journal_mode = WAL');
339	+      await holder.client.execute(
340	+        "DELETE FROM model_catalog WHERE harness = 'codex' AND model = 'gpt-6.1-terra'",
341	+      );
342	+      for (const suffix of ['', '-wal', '-shm'])
343	+        await copyFile(`${original}${suffix}`, join(copy, `gateway.db${suffix}`));
344	+    } finally {
345	+      holder.close();
346	+    }
347	+    const dbFile = join(copy, 'gateway.db');
348	+    const before = await storeBytes(dbFile);
349	+    expect(Object.keys(before)).toContain('gateway.db-wal');
350	+    const report = await cli(
351	+      env(dbFile, { byHarness: { codex: { model: 'gpt-6.1-terra', effort: 'medium' } } }),
352	+    );
353	+    expect(report.code, report.out).toBe(0);
354	+    expect(report.out).toMatch(/ok\s+Default model\s+gpt-6.1-terra/);
355	+    expect((await storedCatalog(dbFile)).some((row) => row.model === 'gpt-6.1-terra')).toBe(false);
356	+    expect(await storeBytes(dbFile)).toEqual(before);
357	+    expect((await readdir(copy)).sort()).toEqual([
358	+      'gateway.db',
359	+      'gateway.db-shm',
360	+      'gateway.db-wal',
361	+    ]);
362	+  });
363	+});
