36	/**
37	 * First-run preflight (docs/11): is this machine ready to run GraphGoblin? Each check reports
38	 * `ok`, `warn` (works, but something is missing or will be set up on first start), or `fail`
39	 * (runs will not work until it is fixed). Served at `GET /system/preflight` and printed by
40	 * `graphgoblin-api --preflight`. Nothing here spawns a Codex session or changes any state.
41	 */
42	
43	export const PreflightStatusSchema = z.enum(['ok', 'warn', 'fail']);
44	export type PreflightStatus = z.infer<typeof PreflightStatusSchema>;
45	
46	export const PreflightCheckSchema = z.object({
47	  state: HarnessReadinessStateSchema.optional(),
48	  id: z.string(),
49	  label: z.string(),
50	  status: PreflightStatusSchema,
51	  message: z.string(),
52	});
53	export type PreflightCheck = z.infer<typeof PreflightCheckSchema>;
54	
55	export const PreflightReportSchema = z.object({
56	  /** False when any check failed. Warnings do not make the report fail. */
57	  ok: z.boolean(),
58	  checks: z.array(PreflightCheckSchema),
59	});
60	export type PreflightReport = z.infer<typeof PreflightReportSchema>;
61	
62	export const SUPPORTED_NODE_MAJOR = 22;
63	
64	/** Where the checks read their facts from: the running container, or the configuration alone. */
65	export interface PreflightSources {
66	  config: ApiConfig;
67	  /** Default: `process.versions.node`. */
68	  nodeVersion?: string;
69	  harnesses: Partial<Record<HarnessId, HarnessPort>>;
70	  /** CLI cannot inspect saved connection settings until its existing store is current. */
71	  ollamaDeferredReason?: string;
72	  /** Migrations still to apply, or `'missing'` when the database file does not exist yet. Throws when unreachable. */
73	  pendingMigrations(): Promise<number | 'missing'>;
74	  /** The Jev API key, if set. Only called once the database is migrated. */
75	  jevKey(): Promise<string | undefined>;
76	  /** Built-in catalog availability; no provider call. Only read after migration. */
77	  jevEnabled(): Promise<boolean>;
78	  /** The model catalog. Only called once the database is migrated. */
79	  catalog(): Promise<ModelCatalogEntry[]>;
80	}
