90	export function checkNode(version: string): PreflightCheck {
91	  const major = Number(/^v?(\d+)/.exec(version)?.[1] ?? NaN);
92	  return major === SUPPORTED_NODE_MAJOR
93	    ? check('node', 'Node.js', 'ok', `Node ${version}`)
94	    : check(
95	        'node',
