102	/** A fresh probe file name; random, so concurrent preflights never share one. */
103	export type ProbeName = () => string;
104	const defaultProbeName: ProbeName = () => `.preflight-${randomUUID()}`;
105	
106	/**
107	 * Prove `dir` is writable by creating a new file in it exclusively (`wx`: never truncates an
108	 * existing file and never follows a symlink at that path) and removing only that file. A name
109	 * that already exists is skipped for the next one. Throws when the directory is not writable.
110	 */
111	export async function probeWritable(
112	  dir: string,
113	  name: ProbeName = defaultProbeName,
114	): Promise<void> {
115	  for (let attempt = 0; ; attempt += 1) {
116	    const path = join(dir, name());
117	    let handle;
118	    try {
119	      handle = await open(path, 'wx');
120	    } catch (error) {
121	      if ((error as NodeJS.ErrnoException).code === 'EEXIST' && attempt < 4) continue;
122	      throw error;
123	    }
124	    await handle.close();
125	    await unlink(path);
126	    return;
127	  }
128	}
