130	export async function checkDataDir(
131	  dir: string,
132	  probeName: ProbeName = defaultProbeName,
133	): Promise<PreflightCheck> {
134	  const fail = (text: string): PreflightCheck => check('data-dir', 'Data directory', 'fail', text);
135	  let isDirectory: boolean;
136	  try {
137	    isDirectory = (await stat(dir)).isDirectory();
138	  } catch (error) {
139	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
140	      return check(
141	        'data-dir',
142	        'Data directory',
143	        'warn',
144	        `${dir} does not exist yet; it is created on first start`,
145	      );
146	    }
147	    return fail(`cannot read ${dir}: ${message(error)}`);
148	  }
149	  if (!isDirectory) return fail(`${dir} exists but is not a directory`);
150	  try {
151	    await probeWritable(dir, probeName);
152	  } catch (error) {
153	    return fail(`${dir} is not writable: ${message(error)}`);
154	  }
155	  return check('data-dir', 'Data directory', 'ok', `${dir} is writable`);
156	}
