158	/** Read the master key the way `loadMasterKey` does, without generating one. */
159	export async function readMasterKey(
160	  config: Pick<ApiConfig, 'dataDir' | 'masterKey'>,
161	): Promise<{ check: PreflightCheck; key?: Buffer }> {
162	  const result = (status: PreflightStatus, text: string, key?: Buffer) => ({
163	    check: check('master-key', 'Master key', status, text),
164	    ...(key ? { key } : {}),
165	  });
166	  if (config.masterKey) {
167	    const key = Buffer.from(config.masterKey, 'base64');
168	    return key.length === 32
169	      ? result('ok', 'taken from GG_MASTER_KEY', key)
170	      : result('fail', 'GG_MASTER_KEY must be base64 for exactly 32 bytes');
171	  }
172	  const file = join(config.dataDir, 'master.key');
173	  let text: string;
174	  try {
175	    text = await readFile(file, 'utf8');
176	  } catch (error) {
177	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
178	      return result(
179	        'warn',
180	        `${file} does not exist yet; a key is generated on first start (back it up, or set GG_MASTER_KEY)`,
181	      );
182	    }
183	    return result('fail', `cannot read ${file}: ${message(error)}`);
184	  }
185	  const key = Buffer.from(text.trim(), 'base64');
186	  return key.length === 32
187	    ? result('ok', `read from ${file}`, key)
188	    : result('fail', `${file} does not contain a base64 32-byte key`);
189	}
190	
191	async function checkHarnesses(
192	  harnesses: Partial<Record<HarnessId, HarnessPort>>,
193	  config: ApiConfig,
194	  ollamaDeferredReason?: string,
195	): Promise<PreflightCheck[]> {
196	  const checks: PreflightCheck[] = [];
197	  await Promise.all(
198	    Object.entries(harnesses).map(async ([id, harness]) => {
199	      if (!harness) return;
200	      const label = `Harness ${id}`;
201	      if (id === 'ollama' && ollamaDeferredReason) {
202	        checks.push({
203	          state: 'unknown',
204	          ...check('harness.ollama', label, 'warn', ollamaDeferredReason),
205	        });
206	        return;
207	      }
208	      const unavailableStatus =
209	        (id === 'claude' && !config.defaults.byHarness.claude) ||
210	        (id === 'ollama' && config.defaults.byHarness.ollama?.model === undefined) ||
211	        (id === 'codex' && ollamaOnly(config))
212	          ? ('warn' as const)
213	          : ('fail' as const);
214	      try {
215	        const result = await harness.preflight();
216	        const version = result.version ? ` ${result.version}` : '';
217	        checks.push({
218	          state: result.state,
219	          ...(result.ok
220	            ? check(
221	                `harness.${id}`,
222	                label,
223	                'ok',
224	                id === 'ollama'
225	                  ? readinessDetail('ollama', 'ready')
226	                  : `${id}${version} is installed and logged in`,
227	              )
228	            : check(
229	                `harness.${id}`,
230	                label,
231	                unavailableStatus,
232	                result.problems.join(' ') || readinessMessage(id, result.state),
233	              )),
234	        });
235	      } catch {
236	        checks.push({
237	          state: 'unknown',
238	          ...check(`harness.${id}`, label, unavailableStatus, readinessMessage(id, 'unknown')),
239	        });
240	      }
241	    }),
242	  );
243	  if (ollamaOnly(config) && !harnesses.codex)
244	    checks.push(
245	      check(
246	        'harness.codex',
247	        'Harness codex',
248	        'warn',
249	        'Codex is optional for the configured Ollama-only defaults',
250	      ),
251	    );
252	  if (checks.length === 0) {
253	    checks.push(check('harness', 'Harness', 'fail', 'no harness adapter is configured'));
254	  }
255	  return checks;
256	}
257	
258	function ollamaOnly(config: ApiConfig): boolean {
259	  return (
260	    config.defaults.byHarness.ollama?.model !== undefined &&
261	    config.defaults.byHarness.codex === undefined
262	  );
263	}
264	
265	function checkDefaultModel(
266	  model: string | undefined,
267	  catalog: ModelCatalogEntry[],
268	  seeded: boolean,
269	): PreflightCheck {
270	  const entry = catalog.find((e) => e.harness === 'codex' && e.model === model);
271	  const where = seeded ? 'the model catalog' : 'the default catalog seeded on first start';
272	  if (!entry) {
273	    return check(
274	      'default-model',
275	      'Default model',
276	      'fail',
277	      `GG_DEFAULTS.byHarness.codex.model "${model}" is not in ${where}; pick a listed harness model and enable it in Settings`,
278	    );
279	  }
280	  if (!entry.enabled) {
281	    return check('default-model', 'Default model', 'warn', `${model} is in ${where} but disabled`);
282	  }
283	  return check(
284	    'default-model',
285	    'Default model',
286	    'ok',
287	    `${model} (${entry.harness}) is in ${where}`,
288	  );
289	}
