291	/** Run every check. Never throws: a check that cannot run reports `fail` with the reason. */
292	export async function runPreflight(sources: PreflightSources): Promise<PreflightReport> {
293	  const { config } = sources;
294	  const checks: PreflightCheck[] = [checkNode(sources.nodeVersion ?? process.versions.node)];
295	  checks.push(await checkDataDir(config.dataDir));
296	  checks.push((await readMasterKey(config)).check);
297	
298	  let migrated = false;
299	  try {
300	    const pending = await sources.pendingMigrations();
301	    if (pending === 'missing') {
302	      checks.push(
303	        check(
304	          'database',
305	          'Database',
306	          'warn',
307	          'the database does not exist yet; it is created and migrated on first start',
308	        ),
309	      );
310	    } else if (pending > 0) {
311	      checks.push(
312	        check(
313	          'database',
314	          'Database',
315	          'warn',
316	          `${String(pending)} migration(s) pending; they are applied on the next start`,
317	        ),
318	      );
319	    } else {
320	      migrated = true;
321	      checks.push(check('database', 'Database', 'ok', 'reachable and migrated'));
322	    }
323	  } catch (error) {
324	    checks.push(
325	      check(
326	        'database',
327	        'Database',
328	        'fail',
329	        error instanceof UnsupportedStoreError
330	          ? `${error.reason}. Start refuses this store and converts nothing; to start fresh, list what a reset removes with ${RESET_COMMAND} ${dataDirArgument(config.dataDir)}`
331	          : `not reachable: ${message(error)}`,
332	      ),
333	    );
334	  }
335	
336	  checks.push(...(await checkHarnesses(sources.harnesses, config, sources.ollamaDeferredReason)));
337	
338	  if (!migrated) {
339	    checks.push(
340	      check('jev', 'Jev', 'warn', 'not checked until the database is migrated; Jev is optional'),
341	    );
342	  } else {
343	    try {
344	      const key = (await sources.jevKey())?.trim();
345	      checks.push(
346	        key
347	          ? check(
348	              'jev',
349	              'Jev',
350	              'ok',
351	              `API key set (secret "${JEV_SECRET}")${(await sources.jevEnabled()) ? '' : ' (disabled in Settings)'}`,
352	            )
353	          : check(
354	              'jev',
355	              'Jev',
356	              'warn',
357	              `no API key in secret "${JEV_SECRET}"; Jev is optional; its classifier is unavailable until a key is configured`,
358	            ),
359	      );
360	    } catch (error) {
361	      checks.push(check('jev', 'Jev', 'warn', `cannot read the Jev key: ${message(error)}`));
362	    }
363	  }
364	
365	  try {
366	    const catalog = migrated ? await sources.catalog() : DEFAULT_MODEL_CATALOG;
367	    if (!ollamaOnly(config))
368	      checks.push(checkDefaultModel(config.defaults.byHarness.codex?.model, catalog, migrated));
369	    const ollama = config.defaults.byHarness.ollama;
370	    if (ollama?.model !== undefined) {
371	      const entry = catalog.find((row) => row.harness === 'ollama' && row.model === ollama.model);
372	      if (!migrated || !entry)
373	        checks.push(
374	          check(
375	            'default-model.ollama',
376	            'Ollama default model',
377	            'warn',
378	            'The configured Ollama model is not checked until discovery',
379	          ),
380	        );
381	      else {
382	        const problem =
383	          entry.availability && entry.availability.state !== 'available'
384	            ? (entry.availability.reason ??
385	              'The configured Ollama model is unavailable; refresh models in Settings')
386	            : !entry.enabled
387	              ? 'The configured Ollama model is disabled'
388	              : !ollama.effort || !entry.efforts.includes(ollama.effort)
389	                ? 'Configure an explicit supported Ollama thinking control'
390	                : undefined;
391	        checks.push(
392	          check(
393	            'default-model.ollama',
394	            'Ollama default model',
395	            problem ? 'fail' : 'ok',
396	            problem ?? 'Exact Ollama model and effort are configured and available',
397	          ),
398	        );
399	      }
400	      if (!sources.harnesses.ollama && !sources.ollamaDeferredReason)
401	        checks.push(
402	          check(
403	            'harness.ollama',
404	            'Harness ollama',
405	            'fail',
406	            'The configured Ollama harness is unavailable',
407	          ),
408	        );
409	    }
410	    const defaults = config.defaults.byHarness.claude;
411	    if (defaults) {
412	      const entry = catalog.find((row) => row.harness === 'claude' && row.model === defaults.model);
413	      const problem = !entry
414	        ? 'The configured Claude model is not in the catalog'
415	        : !defaults.effort || !entry.efforts.includes(defaults.effort)
416	          ? 'Configure an explicit supported Claude reasoning effort'
417	          : !entry.enabled
418	            ? 'The configured Claude model is disabled'
419	            : undefined;
420	      checks.push(
421	        check(
422	          'default-model.claude',
423	          'Claude default model',
424	          problem ? 'fail' : 'ok',
425	          problem ?? 'Exact Claude model and effort are configured',
426	        ),
427	      );
428	      if (!sources.harnesses.claude)
429	        checks.push(
430	          check(
431	            'harness.claude',
432	            'Harness claude',
433	            'fail',
434	            'The configured Claude harness is unavailable',
435	          ),
436	        );
437	    }
438	  } catch (error) {
439	    checks.push(
440	      check('default-model', 'Default model', 'fail', `cannot read the catalog: ${message(error)}`),
441	    );
442	  }
443	
444	  return { ok: checks.every((c) => c.status !== 'fail'), checks };
445	}
