447	/** Facts from a running container, for `GET /system/preflight`. */
448	export function containerPreflightSources(container: Container): PreflightSources {
449	  return {
450	    config: container.config,
451	    harnesses: container.ports.harnesses,
452	    pendingMigrations: () => container.handle.pendingMigrations(),
453	    jevKey: () => container.repos.secretsFor(LOCAL_OWNER).resolve(JEV_SECRET),
454	    jevEnabled: async () =>
455	      (await container.repos.classifiers.findOne(LOCAL_OWNER, 'jev'))?.enabled ?? true,
456	    catalog: () => container.repos.catalog.list(),
457	  };
