460	function isMissing(error: unknown): boolean {
461	  return (error as NodeJS.ErrnoException).code === 'ENOENT';
462	}
463	
464	/**
465	 * Whether the server's start can create `file`: it creates the missing directories above it, so
466	 * the nearest existing ancestor must be a writable directory. Throws with the reason otherwise.
467	 */
468	export async function assertCreatable(file: string, probeName?: ProbeName): Promise<void> {
469	  let dir = dirname(file);
470	  for (;;) {
471	    let isDirectory: boolean;
472	    try {
473	      isDirectory = (await stat(dir)).isDirectory();
474	    } catch (error) {
475	      if (!isMissing(error) || dirname(dir) === dir) throw error;
476	      dir = dirname(dir);
477	      continue;
478	    }
479	    if (!isDirectory) throw new Error(`${file} cannot be created: ${dir} is not a directory`);
480	    try {
481	      await probeWritable(dir, probeName);
482	    } catch (error) {
483	      throw new Error(`${file} cannot be created: ${dir} is not writable (${message(error)})`, {
484	        cause: error,
485	      });
486	    }
487	    return;
488	  }
489	}
490	
491	/** The connection preflight inspects a store through: read-only for a file on disk. */
492	interface InspectedDatabase {
493	  client: ReturnType<typeof openReadOnlyDatabaseClient>;
494	  db: Database;
495	  pendingMigrations(): Promise<number>;
496	  close(): void;
497	}
498	
499	/** What the CLI can learn about the database before the server has started. */
500	type DatabaseState =
501	  | { kind: 'missing' }
502	  | { kind: 'broken'; error: unknown }
503	  | { kind: 'open'; handle: InspectedDatabase };
504	
505	async function inspectDatabase(url: string): Promise<DatabaseState> {
506	  const file = databaseFilePath(url);
507	  if (file !== undefined) {
508	    try {
509	      await stat(file);
510	    } catch (error) {
511	      if (!isMissing(error)) return { kind: 'broken', error };
512	      try {
513	        await assertCreatable(file);
514	        return { kind: 'missing' };
515	      } catch (reason) {
516	        return { kind: 'broken', error: reason };
517	      }
518	    }
519	  }
520	  try {
521	    if (file !== undefined) {
522	      // The same read-only connection as startup's guard: a refused or healthy store keeps its
523	      // database and write-ahead log bytes (a mutable connection checkpoints the log on close).
524	      const client = openReadOnlyDatabaseClient(file);
525	      return {
526	        kind: 'open',
527	        handle: {
528	          client,
529	          db: databaseView(client),
530	          pendingMigrations: () => pendingMigrationCount(client),
531	          close: () => client.close(),
532	        },
533	      };
534	    }
535	    return { kind: 'open', handle: openDatabase({ url }) };
536	  } catch (error) {
537	    return { kind: 'broken', error };
538	  }
539	}
540	
541	/** Never initializes the singleton or guesses over saved settings in an unverified store. */
542	async function inspectedOllamaConnection(
543	  database: DatabaseState,
544	  config: ApiConfig,
545	): Promise<
546	  | { connection: OllamaConnection; deferredReason?: never }
547	  | { connection?: never; deferredReason: string }
548	> {
549	  const fallback = { enabled: config.ollamaEnabled, baseUrl: config.ollamaUrl, revision: 1 };
550	  if (database.kind === 'missing') return { connection: fallback };
551	  if (database.kind === 'broken')
552	    return { deferredReason: 'Ollama is not checked until the database can be read' };
553	  try {
554	    await guardCurrentStore(database.handle.client);
555	    if ((await database.handle.pendingMigrations()) !== 0)
556	      return { deferredReason: 'Ollama is not checked until the database is migrated' };
557	    const row = await database.handle.db.query.ollamaConnection.findFirst({
558	      where: (row, { eq }) => eq(row.id, 'gateway'),
559	    });
560	    return {
561	      connection: row
562	        ? OllamaConnectionSchema.parse({
563	            enabled: row.enabled,
564	            baseUrl: row.baseUrl,
565	            revision: row.revision,
566	          })
567	        : fallback,
568	    };
569	  } catch {
570	    return { deferredReason: 'Ollama is not checked until the database is current and readable' };
571	  }
572	}
573	
574	export interface ConfigPreflightOptions {
575	  /** Replace the native harness map (tests). */
576	  harnesses?: Partial<Record<HarnessId, HarnessPort>>;
577	  nodeVersion?: string;
578	}
579	
580	/**
581	 * Facts from the configuration alone, for the CLI before the server has started. Opens the
582	 * database only when its file exists, so a first run creates nothing; a missing file is a
583	 * warning only when the server's start could create it.
584	 */
585	export async function configPreflightSources(
586	  config: ApiConfig,
587	  options: ConfigPreflightOptions = {},
588	): Promise<PreflightSources & { close(): void }> {
589	  const database = await inspectDatabase(config.dbUrl);
590	  const { key } = await readMasterKey(config);
591	  const ollama = await inspectedOllamaConnection(database, config);
592	  const harnesses = options.harnesses ?? {
593	    codex: createCodexAdapters({
594	      ...(config.defaults.byHarness.codex?.model !== undefined
595	        ? { model: config.defaults.byHarness.codex.model }
596	        : {}),
597	      ...(config.defaults.byHarness.codex?.effort !== undefined
598	        ? { effort: config.defaults.byHarness.codex.effort }
599	        : {}),
600	      ...(config.codexBinary ? { codexBinary: config.codexBinary } : {}),
601	    }).harness,
602	    claude: new ClaudeHarness({ ...(config.claudeBinary ? { binary: config.claudeBinary } : {}) }),
603	    ollama: new OllamaHarness({
604	      snapshot: () =>
605	        ollama.connection
606	          ? Promise.resolve({ connection: ollama.connection, models: [] })
607	          : Promise.reject(new Error(ollama.deferredReason)),
608	    }),
609	  };
610	  const base = {
611	    config,
612	    harnesses,
613	    ...(ollama.deferredReason ? { ollamaDeferredReason: ollama.deferredReason } : {}),
614	    ...(options.nodeVersion ? { nodeVersion: options.nodeVersion } : {}),
615	  };
616	  if (database.kind !== 'open') {
617	    const { kind } = database;
618	    const failure = kind === 'broken' ? database.error : undefined;
619	    return {
620	      ...base,
621	      pendingMigrations: () =>
622	        kind === 'missing'
623	          ? Promise.resolve('missing' as const)
624	          : Promise.reject(failure instanceof Error ? failure : new Error(String(failure))),
625	      jevKey: () => Promise.resolve(undefined),
626	      jevEnabled: () => Promise.resolve(true),
627	      catalog: () => Promise.resolve(DEFAULT_MODEL_CATALOG),
628	      close: () => undefined,
629	    };
630	  }
631	  const { handle } = database;
632	  return {
633	    ...base,
634	    // A store start would refuse is reported as such, never as migrations it would apply.
635	    pendingMigrations: async () => {
636	      await guardCurrentStore(handle.client);
637	      return handle.pendingMigrations();
638	    },
639	    jevKey: () =>
640	      key
641	        ? new SqliteSecrets(handle.db, { now: () => new Date() }, key, LOCAL_OWNER).resolve(
642	            JEV_SECRET,
643	          )
644	        : Promise.resolve(undefined),
645	    catalog: async () => projectStartupModelCatalog(await new SqliteModelCatalog(handle.db).list()),
646	    jevEnabled: async () =>
647	      (await new SqliteClassifierModels(handle.db).findOne(LOCAL_OWNER, 'jev'))?.enabled ?? true,
648	    close: () => handle.close(),
649	  };
650	}
651	
652	const MARK: Record<PreflightStatus, string> = { ok: 'ok', warn: 'WARN', fail: 'FAIL' };
653	
654	/** A plain-text table for the terminal. */
655	export function formatPreflight(report: PreflightReport): string {
656	  const rows = report.checks.map((c) => [MARK[c.status], c.label, c.message] as const);
657	  const width = (i: 0 | 1, title: string) =>
658	    Math.max(title.length, ...rows.map((r) => r[i].length));
659	  const w0 = width(0, 'STATUS');
660	  const w1 = width(1, 'CHECK');
661	  const line = (a: string, b: string, c: string) => `  ${a.padEnd(w0)}  ${b.padEnd(w1)}  ${c}`;
662	  const failed = report.checks.filter((c) => c.status === 'fail').length;
663	  const warned = report.checks.filter((c) => c.status === 'warn').length;
664	  return [
665	    'GraphGoblin preflight',
666	    '',
667	    line('STATUS', 'CHECK', 'DETAIL'),
668	    ...rows.map((r) => line(r[0], r[1], r[2])),
669	    '',
670	    `${String(failed)} failed, ${String(warned)} warning(s): ${
671	      report.ok ? 'ready to start' : 'fix the failed checks before starting'
672	    }`,
673	    '',
674	  ].join('\n');
675	}
676	
677	export interface PreflightCliOptions extends ConfigPreflightOptions {
678	  env?: NodeJS.ProcessEnv;
679	  write?: (text: string) => void;
680	}
681	
682	/** `graphgoblin-api --preflight`: print the checks and return the exit code (0 unless a check failed). */
683	export async function runPreflightCli(options: PreflightCliOptions = {}): Promise<number> {
684	  const write = options.write ?? ((text: string) => process.stdout.write(text));
685	  let config: ApiConfig;
686	  try {
687	    config = loadConfig(options.env ?? process.env);
688	  } catch (error) {
689	    write(`GraphGoblin preflight\n\n  FAIL  configuration  ${message(error)}\n`);
690	    return 1;
691	  }
692	  const sources = await configPreflightSources(config, options);
693	  try {
694	    const report = await runPreflight(sources);
695	    write(formatPreflight(report));
696	    return report.ok ? 0 : 1;
697	  } finally {
698	    sources.close();
699	  }
700	}
