22	  | { status: 'ready'; model: string; effort: Effort }
23	  | {
24	      status: 'invalid';
25	      code:
26	        | 'MODEL_UNRESOLVED'
27	        | 'EFFORT_UNRESOLVED'
28	        | 'MODEL_NOT_IN_CATALOG'
29	        | 'MODEL_HARNESS_MISMATCH'
30	        | 'EFFORT_UNSUPPORTED';
31	      path: 'model' | 'effort';
32	      message: string;
33	    }
34	  | {
35	      status: 'unavailable';
36	      code: 'MODEL_DISABLED' | 'MODEL_UNAVAILABLE';
37	      path: 'model';
38	      message: string;
39	    };
40	
41	/** Inherit each field independently, within one harness, from loop, owner, then process. */
42	export function inheritedHarnessDefaults(
43	  input: Pick<
44	    HarnessModelResolutionInput,
45	    'harness' | 'loopDefaults' | 'ownerDefaults' | 'processDefaults'
46	  >,
47	): HarnessModelDefaults {
48	  const levels = [input.loopDefaults, input.ownerDefaults, input.processDefaults].map(
49	    (defaults) => defaults.byHarness[input.harness],
50	  );
51	  return {
52	    model: levels.find((level) => level?.model !== undefined)?.model,
53	    effort: levels.find((level) => level?.effort !== undefined)?.effort,
54	  };
55	}
56	
57	/** Resolve only the selected harness's defaults; catalog effort is guidance, never an implicit default. */
58	export function resolveHarnessModel(input: HarnessModelResolutionInput): HarnessModelResolution {
59	  const { harness, catalog } = input;
60	  const inherited = inheritedHarnessDefaults(input);
61	  const model = input.model ?? inherited.model;
62	  const effort = input.effort ?? inherited.effort;
63	  if (!model)
64	    return {
65	      status: 'invalid',
66	      code: 'MODEL_UNRESOLVED',
67	      path: 'model',
68	      message: 'No model is configured for the selected harness',
69	    };
70	  const entry = catalog.find((row) => row.harness === harness && row.model === model);
71	  if (!entry) {
72	    if (harness === 'ollama')
73	      return {
74	        status: 'unavailable',
75	        code: 'MODEL_UNAVAILABLE',
76	        path: 'model',
77	        message: 'Connect Ollama in Settings, refresh models and choose the exact installed model',
78	      };
79	    const mismatch = catalog.some((row) => row.model === model);
80	    return {
81	      status: 'invalid',
82	      code: mismatch ? 'MODEL_HARNESS_MISMATCH' : 'MODEL_NOT_IN_CATALOG',
83	      path: 'model',
84	      message: mismatch
85	        ? 'The selected model belongs to another harness'
86	        : 'The selected model is not in the catalog',
87	    };
88	  }
89	  if (entry.availability && entry.availability.state !== 'available')
90	    return {
91	      status: 'unavailable',
92	      code: 'MODEL_UNAVAILABLE',
93	      path: 'model',
94	      message:
95	        entry.availability.reason ?? 'The selected model is unavailable on the configured service',
96	    };
97	  if (!effort)
98	    return {
99	      status: 'invalid',
100	      code: 'EFFORT_UNRESOLVED',
101	      path: 'effort',
102	      message: 'No reasoning effort is configured for the selected harness',
103	    };
104	  if (
105	    !entry.efforts.includes(effort) ||
106	    (harness === 'claude' &&
107	      input.claudeCapabilities !== undefined &&
108	      !input.claudeCapabilities.some(
109	        (capability) => capability.model === model && capability.efforts.includes(effort),
110	      ))
111	  )
112	    return {
113	      status: 'invalid',
114	      code: 'EFFORT_UNSUPPORTED',
115	      path: 'effort',
116	      message: 'The selected reasoning effort is not supported by this model',
117	    };
118	  if (!entry.enabled)
119	    return {
120	      status: 'unavailable',
121	      code: 'MODEL_DISABLED',
122	      path: 'model',
123	      message: 'The selected model is disabled',
124	    };
125	  return { status: 'ready', model, effort };
126	}
