134	/** Authored defaults are configuration, including values overridden by a higher layer. */
135	export function validateHarnessDefaults(
136	  input: Pick<
137	    HarnessModelResolutionInput,
138	    'loopDefaults' | 'ownerDefaults' | 'processDefaults' | 'catalog'
139	  >,
140	): HarnessDefaultsIssue[] {
141	  const levels = [
142	    ['loop', input.loopDefaults],
143	    ['owner', input.ownerDefaults],
144	    ['process', input.processDefaults],
145	  ] as const;
146	  const issues: HarnessDefaultsIssue[] = [];
147	  for (const [index, [level, defaults]] of levels.entries()) {
148	    for (const [harness, fields] of Object.entries(defaults.byHarness) as [
149	      HarnessId,
150	      { model?: string; effort?: Effort },
151	    ][]) {
152	      // Dynamic Ollama discovery cannot make a structurally valid process choice block boot
153	      // or prevent its correction. Actual selected-node resolution remains strict.
154	      if (level === 'process' && harness === 'ollama' && fields.model !== undefined) continue;
155	      const lower = levels.slice(index).map(([, entry]) => entry.byHarness[harness]);
156	      const model = lower.find((entry) => entry?.model !== undefined)?.model;
157	      const entry = input.catalog.find((row) => row.harness === harness && row.model === model);
158	      let resolution: HarnessDefaultsIssue['resolution'] | undefined;
159	      if (fields.model !== undefined && !entry) {
160	        const mismatch = input.catalog.some((row) => row.model === fields.model);
161	        resolution = {
162	          status: 'invalid',
163	          code: mismatch ? 'MODEL_HARNESS_MISMATCH' : 'MODEL_NOT_IN_CATALOG',
164	          path: 'model',
165	          message: mismatch
166	            ? 'The default model belongs to another harness'
167	            : 'The default model is not in the catalog',
168	        };
169	      } else if (
170	        fields.effort !== undefined &&
171	        !(
172	          harness === 'ollama' &&
173	          entry?.availability &&
174	          entry.availability.state !== 'available'
175	        ) &&
176	        (!entry || !entry.efforts.includes(fields.effort))
177	      ) {
178	        resolution = {
179	          status: 'invalid',
180	          code: entry ? 'EFFORT_UNSUPPORTED' : 'MODEL_UNRESOLVED',
181	          path: entry ? 'effort' : 'model',
182	          message: entry
183	            ? 'The default reasoning effort is not supported by its model'
184	            : 'No model is configured for this reasoning effort default',
185	        };
186	      }
187	      if (resolution) issues.push({ level, harness, resolution });
188	    }
189	  }
190	  return issues;
